import json, glob, re, os
BASE = '/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory'
R = {}
for f in sorted(glob.glob(BASE + '/raw/*.json')):
    d = json.load(open(f))
    recs = d if isinstance(d, list) else d.get('features') or d.get('records')
    for r in recs:
        r['_f'] = os.path.basename(f)[:-5]
        R[r['id']] = r


def show(r):
    s = f"[{r['id']}|{r['area']}] {r['name']} :: {r['what']}"
    if r['ui']:
        s += f"\n  ui: {' | '.join(r['ui'])}"
    if r['mcp']:
        s += f"\n  mcp: {', '.join(r['mcp'])}"
    if r['requires']:
        s += f"\n  req: {' | '.join(r['requires'])}"
    for x in r['details']:
        s += f"\n  - {x}"
    s += f"\n  ev: {r['evidence']}"
    return s

