/// Which keys a screen recording writes into its cursor files (road map creator-jobs CU6,
/// spec §11 CU-60, CU-62): none, or each shortcut spelled and a time-only mark for every other
/// key-down, under Input Monitoring. An enum so a later mode needs no rename; `record_screen`'s
/// `keys` spells it.
enum RecordingKeys: String, CaseIterable {
    case off
    case shortcuts
}

/// Where a screen recording's pointer goes (road map creator-jobs CU3c, spec §11 CU-31, CU-36):
/// `separate` — not in the movie, written to the cursor file for Frame Job to draw — or
/// `inPicture`, burned in by ScreenCaptureKit as before CU3c. `record_screen`'s `cursor` spells it.
enum RecordingCursor: String, CaseIterable {
    case separate
    case inPicture = "in_picture"

    /// CU-36 (b), (c), amended at CU0d: a window or picked recording's default. The
    /// quiet-machine re-run of CU-S2's window rows settled their anchor as E1, so it is
    /// `.separate`, as a display's is.
    static let windowDefault: RecordingCursor = .separate

    /// CU-36, amended at CU0d: `.separate` for a display, `windowDefault` (`.separate`) for a
    /// window or a picked source, and `.separate` for a voice-over or a camera alone, which have
    /// no pointer to draw.
    static func defaultFor(_ source: RecordingSource) -> RecordingCursor {
        switch source {
        case .display: return .separate
        case .window, .picked: return windowDefault
        case .voiceOver, .camera: return .separate
        }
    }
}

/// Every control of the recorder panel and every argument of
/// `record_screen`, as one value. `microphone` is an
/// `AVCaptureDevice.uniqueID`, nil for off; `rate` is 30 or 60 (a camera
/// recording's is its format's, `CameraDevices.canvasRate`). `camera` is an
/// `AVCaptureDevice.uniqueID`, set with `source` `.camera`, or beside a
/// display, window or picked source (CAM-9), and `cameraFormat` its format
/// as `CameraDevices.spelled` writes it, nil for Best and set only with
/// `camera` (spec §11 CAM-6).
struct RecordingChoice: Equatable {
    var source: RecordingSource = .display(CGMainDisplayID())
    var includeFrameJobWindows: Bool = false
    var microphone: String? = nil
    var systemAudio: Bool = true
    var showClicks: Bool = false
    var rate: Int = 60
    var resolution: RecordingResolution = .nominal
    var destination: RecordingDestination = .newProject
    var folder: URL = RecordingFiles.folder()
    var camera: String? = nil
    var cameraFormat: String? = nil
    /// Enhance Voice on the voice's clips after the landing; only with a microphone (AU-68, AU-69).
    var enhanceMicrophone: Bool = false
    /// Record shortcuts (spec §11 CU-62): only with a display, window or picked source.
    var keys: RecordingKeys = .off
    /// The Cursor row (spec §11 CU-36): nil follows the source's default.
    var cursor: RecordingCursor? = nil
    /// The polish on landing (spec §11 CU-100…CU-102): Auto Zoom, Add Shortcut Overlays and
    /// Speed Up Typing over the landed screen clips, each its own undo step after the landing.
    var autoZoom: Bool = false
    var shortcutOverlays: Bool = false
    var speedUpTyping: Bool = false
    /// The camera beside the screen's layout and its cutout on landing (spec §11 CO-80…CO-82).
    var cameraLayout: RecordingCameraLayout = .cornerSquare
    var cameraCutout: Bool = false

    /// The cursor this recording is made with: the choice, else the source's default.
    var effectiveCursor: RecordingCursor { cursor ?? .defaultFor(source) }
}

// MARK: - Where the files go

/// Decision 2 (road map 3 §0): a recording is ORIGINAL footage and lives in
------
import Foundation

// MARK: - The cursor in the model and the recipe

// The read-only mirror of `core/src/model_cursor.rs` (format 38, spec §11
// CU-30, CU-39) and of the recipe layer's `cursor` key (CU-32). Nothing here
// draws: the compositor's use of `RecipeCursor` is road map creator-jobs
// CU3a2's. Every decode is lenient, the core's defaults standing in for a key
// that does not read, as the other snapshot types do.

/// Which pointer a clip draws: the images the file recorded, or Frame Job's
/// arrow (`video.cursor.style`).
enum CursorStyle: String, Codable, CaseIterable {
    case recorded, arrow
}

/// What a click draws (`video.cursor.clicks`). The core spells "no ripple"
/// `none`, which is `off` here: a case named `none` beside `Optional.none`
/// is a compiler warning.
enum CursorClicks: String, Codable, CaseIterable {
    case off = "none"
    case ripple
}

/// A clip's `video.cursor` (CU-30). `scale` and `clickSize` animate in an
/// action; `show`, `style`, `clicks` and `clickColor` switch at its end;
/// `smoothing` and `hideIdle` are read from the clip's base props only.
struct CursorProps: Codable, Equatable {
    var show: Bool
    /// 0.25…8.
    var scale: Double
    var style: CursorStyle
    /// 0…1 (spec §11 CU-21).
    var smoothing: Double
    /// Seconds, 0.5…30, or nil: never hidden.
    var hideIdle: Double?
    var clicks: CursorClicks
    /// A CSS colour (spec §11 G-12), as stored.
    var clickColor: String
    /// 0.25…4.
    var clickSize: Double

    static let defaultClickColor = "#ffffffcc"

    init(
        show: Bool = true, scale: Double = 1, style: CursorStyle = .recorded,
        smoothing: Double = 0, hideIdle: Double? = nil, clicks: CursorClicks = .off,
        clickColor: String = CursorProps.defaultClickColor, clickSize: Double = 1
    ) {
        self.show = show
        self.scale = scale
        self.style = style
        self.smoothing = smoothing
        self.hideIdle = hideIdle
        self.clicks = clicks
        self.clickColor = clickColor
        self.clickSize = clickSize
    }

    init(from decoder: Decoder) throws {
            show: show, scale: scale, style: style, clicks: clicks, clickColor: clickColor,
            clickSize: clickSize)
    }
